import re
import urllib.request

def main(url: str):
    # 1. Parse the GitHub URL to extract owner and repo
    match = re.search(r'github\.com/([^/]+)/([^/?]+)', url)
    if not match:
        return {"file_structure": "Error: Invalid GitHub URL format."}

    owner = match.group(1)
    repo = match.group(2)

    # 2. Fetch the recursive tree from GitHub API
    branches = ['main', 'master']
    tree_data = None

    for branch in branches:
        api_url = f"https://api.github.com/repos/{owner}/{repo}/git/trees/{branch}?recursive=1"
        try:
            # Adding a User-Agent is recommended for GitHub API requests
            req = urllib.request.Request(api_url, headers={'User-Agent': 'Dify-Workflow'})
            with urllib.request.urlopen(req) as response:
                if response.status == 200:
                    data = json.loads(response.read().decode())
                    if 'tree' in data:
                        tree_data = data
                        break
        except Exception:
            continue

    if not tree_data:
        return {"file_structure": "Error: Could not fetch repository tree. Ensure the repository is public and the URL is correct."}

    # 3. Format the file structure as a text-based tree view
    paths = [item['path'] for item in tree_data['tree']]
    paths.sort()

    tree_lines = []

    for i, path in enumerate(paths):
        parts = path.split('/')
        depth = len(parts)

        # Build the prefix for indentation and vertical lines
        prefix = ""
        for d in range(depth - 1):
            # Check if the current path segment is the last sibling at this depth
            # by peeking at the next path in the sorted list
            is_last = True
            if i < len(paths) - 1:
                next_parts = paths[i+1].split('/')
                # If the next path shares the same prefix up to this depth, the branch continues
                if len(next_parts) > d and parts[:d+1] == next_parts[:d+1]:
                    is_last = False

            if is_last:
                prefix += "    " # 4 spaces for closed branches
            else:
                prefix += "│   " # Vertical bar for open branches

        # Add the connector for the current item (file or folder)
        # Check if this item is the last sibling of its parent
        is_last_item = True
        if i < len(paths) - 1:
            next_parts = paths[i+1].split('/')
            # If the next path has the same parent, this is not the last item
            if len(next_parts) >= depth and parts[:-1] == next_parts[:-1]:
                is_last_item = False

        if is_last_item:
            prefix += "└── "
        else:
            prefix += "├── "

        tree_lines.append(prefix + parts[-1])

    return {"file_structure": "\n".join(tree_lines)}"
